"""Automatic checks for the Python Readiness Test. Do not edit this file."""
import pytest

import readiness_test as rt


# Task 1
@pytest.mark.parametrize("amount, band", [
    (15000, "High"), (10000, "High"), (9999.99, "Medium"),
    (1000, "Medium"), (999, "Low"), (250.5, "Low"), (0, "Low"),
])
def test_task1_classify_amount(amount, band):
    assert rt.classify_amount(amount) == band


# Task 2
def test_task2_monthly_fee():
    assert rt.monthly_fee(5000) == 50.0
    assert rt.monthly_fee(100) == 2.0
    assert rt.monthly_fee(5000, rate=0.005) == 25.0
    assert rt.monthly_fee(300, minimum=5) == 5
    assert rt.monthly_fee(1234.56) == 12.35


# Task 3
def test_task3_first_over_limit():
    assert rt.first_over_limit([200, 450, 9000, 300, 12000], 5000) == 2
    assert rt.first_over_limit([200, 450], 5000) == -1
    assert rt.first_over_limit([], 5000) == -1
    assert rt.first_over_limit([5000, 5001], 5000) == 1


# Task 4
def test_task4_total_by_type():
    assert rt.total_by_type([("card", 120), ("transfer", 500), ("card", 80)]) == {"card": 200, "transfer": 500}
    assert rt.total_by_type([]) == {}
    assert rt.total_by_type([("fee", 2.5)]) == {"fee": 2.5}


# Task 5
def test_task5_branches_in_common():
    assert rt.branches_in_common(["Orchard", "Jurong", "Orchard"], ["Jurong", "Tampines", "Orchard"]) == ["Jurong", "Orchard"]
    assert rt.branches_in_common(["Orchard"], ["Tampines"]) == []


# Task 6
@pytest.mark.parametrize("text, value", [
    ("1,250.50", 1250.5), (" 300 ", 300.0), ("42", 42.0), ("-15.5", -15.5),
    ("n/a", None), ("", None), ("12abc", None),
])
def test_task6_parse_amount(text, value):
    assert rt.parse_amount(text) == value


# Task 7
def test_task7_read_amounts(tmp_path):
    f = tmp_path / "amounts.txt"
    f.write_text("100\n1,200.50\n\nunknown\n75\n")
    assert rt.read_amounts(f) == [100.0, 1200.5, 75.0]


def test_task7_read_amounts_empty_file(tmp_path):
    f = tmp_path / "empty.txt"
    f.write_text("")
    assert rt.read_amounts(f) == []


# Task 8
def test_task8_write_summary(tmp_path):
    f = tmp_path / "summary.txt"
    rt.write_summary(f, {"transfer": 500, "card": 200, "fee": 2.5})
    assert f.read_text().splitlines() == ["card: 200.00", "fee: 2.50", "transfer: 500.00"]
